/** 工具说明的显示语言偏好(按工具名记住,默认中文)与翻译请求队列。 */
import { request } from '../state/store.ts'

const API_TRANSLATE = '/session-context-config/api/translate'
const STORAGE_KEY = 'dsh-session-context-config:tool-lang'

export type ToolLang = 'zh' | 'source'

function storage(): Storage | null {
  try {
    return typeof localStorage === 'undefined' ? null : localStorage
  } catch {
    return null
  }
}

function readAll(): Record<string, ToolLang> {
  try {
    const raw = storage()?.getItem(STORAGE_KEY)
    if (!raw) return {}
    const parsed = JSON.parse(raw) as unknown
    if (!parsed || typeof parsed !== 'object') return {}
    const out: Record<string, ToolLang> = {}
    for (const [name, value] of Object.entries(parsed as Record<string, unknown>)) {
      if (value === 'zh' || value === 'source') out[name] = value
    }
    return out
  } catch {
    return {}
  }
}

/** 默认显示翻译;用户点「文A」切回原文后记住该工具的选择。 */
export function readToolLang(toolName: string): ToolLang {
  return readAll()[toolName] ?? 'zh'
}

export function writeToolLang(toolName: string, lang: ToolLang): void {
  try {
    const all = readAll()
    all[toolName] = lang
    storage()?.setItem(STORAGE_KEY, JSON.stringify(all))
  } catch {
    /* 存储不可用时只影响记忆,不影响本次显示 */
  }
}

const translated = new Map<string, string>()
let queue: Promise<unknown> = Promise.resolve()

/**
 * 翻译一段描述:进程内先查内存,再串行走 Host(避免面板里几十个未知工具同时打模型)。
 * 文本是 key:同一段文本只翻一次,文本变了自然 miss。
 */
export function translateToolText(text: string): Promise<string> {
  const hit = translated.get(text)
  if (hit !== undefined) return Promise.resolve(hit)
  const job = queue.then(async () => {
    const again = translated.get(text)
    if (again !== undefined) return again
    const result = await request<{ zh?: string }>(API_TRANSLATE, { method: 'POST', body: JSON.stringify({ text }) })
    if (typeof result.zh !== 'string' || result.zh.length === 0) throw new Error('翻译失败')
    translated.set(text, result.zh)
    return result.zh
  })
  queue = job.catch(() => undefined)
  return job
}
